import { useFormik } from \"formik\";\ni:
import { useFormik } from "formik";
import * as Yup from "yup";

export default function NameForm() {
  const formik = useFormik({
    initialValues: { name: "" },
    validationSchema: Yup.object({ name: Yup.string().required("Напиши имя") }),
    onSubmit(values) { console.log(values); },
  });
  return <form onSubmit={formik.handleSubmit}>
    <input name="name" aria-label="Имя" value={formik.values.name} onChange={formik.handleChange} onBlur={formik.handleBlur} />
    {formik.touched.name && <p>{formik.errors.name}</p>}
    <button type="submit">Сохранить</button>
  </form>;
}
